/* eslint-disable jsx-a11y/label-has-associated-control */
import React, { useEffect, useState } from 'react';
import Box from '@mui/material/Box';
import Card from '@mui/material/Card';
import TextField from '@mui/material/TextField';
import CameraAltIcon from '@mui/icons-material/CameraAlt';
import { MenuItem, Button, Typography } from '@mui/material';
import FormControl from '@mui/material/FormControl';
import Select from '@mui/material/Select';
import { DemoContainer } from '@mui/x-date-pickers/internals/demo';
import { LocalizationProvider } from '@mui/x-date-pickers/LocalizationProvider';
import { AdapterDayjs } from '@mui/x-date-pickers/AdapterDayjs';
import dayjs from 'dayjs';
// import { toast } from 'react-toastify';
import { DatePicker } from '@mui/x-date-pickers/DatePicker';
import customParseFormat from 'dayjs/plugin/customParseFormat'
import { axios } from '../../utils/axios';
import { IMAGE_URL } from '../../utils/config';
import CountryCode from '../../CountryCode'
import { useMyContext } from '../provider';
import GenerateToastConfig from '../../components/toast-config/GenerateToastConfig';
import PhoneLengthByCountry from '../../PhoneLengthByCountry';
import InputField from '../../components/input/inputField';
import DateFormat from '../../components/dayjsFormat/DateFormat';
import useResponsive from '../../hooks/useResponsive';

dayjs.extend(customParseFormat)

const DOBFormat = 'DD/MM/YYYY';
const ITEM_HEIGHT = 48;
const ITEM_PADDING_TOP = 8;
const MenuProps = {
  PaperProps: {
    style: {
      maxHeight: ITEM_HEIGHT * 4.5 + ITEM_PADDING_TOP,
      width: 250,
    },
  },
};
function AdminProfile() {
  const [selectedFile, setSelectedFile] = useState("/assets/icons/proImage.png");
  const { fetchProfileData, i18 } = useMyContext();
  const [data, setData] = useState(null);
  const [editdata, setEditData] = useState(null);
  const [fname, setFname] = useState('');
  const [lname, setLname] = useState('');
  const [eMails, setEMails] = useState('');
  const [phoneCodes, setPhoneCodes] = useState(data?.phoneCode || '');
  const [phoneNumber, setPhoneNumber] = useState('');
  const [dobs, setDobs] = useState('');
  const [genders, setGenders] = useState('');
  const [selectedCountry, setSelectedCountry] = useState(null);
  const [emailError, setEmailError] = useState('');
  const [isAbove18, setIsAbove18] = useState(true);
  const [error, setError] = useState('');
  const [imageUrl, setImageUrl] = useState(null);
  const [editchange, setEditchange] = useState(false)

  const isMobile = useResponsive('down', 'sm')
  const AdminProfileData = async () => {
    try {
      const res = await axios.get('module/auth/admin/profile');
      if (res.status === 200) {
        setData(res?.data?.data?.profileData);
        setEditData(res?.data?.data?.profileData);
        setImageUrl(res?.data?.data?.profileData?.profileImage);
        setPhoneCodes(res?.data?.data?.profileData?.phoneCode);
        setPhoneNumber(res?.data?.data?.profileData?.phone)
      }
    } catch (err) {
      console.log(err);
    }
  };
  useEffect(() => {
    AdminProfileData();
  }, []);

  const EditAdmin = async () => {
    const updatedValues = new FormData();
    const editId = data._id;
    updatedValues.append('file', selectedFile || data?.profileImage);
    updatedValues.append('phone', phoneNumber || data?.phone);
    updatedValues.append('phoneCode', phoneCodes || data?.phoneCode);
    updatedValues.append('email', eMails || data?.email);
    updatedValues.append('dob', dobs || data?.dob);
    updatedValues.append('firstname', fname || data?.firstname);
    updatedValues.append('lastname', lname || data?.lastname);
    updatedValues.append('gender', genders || data?.gender);
    try {
      const res = await axios.put(`module/auth/admin/${editId}`, updatedValues);
      if (res.status === 200) {
        AdminProfileData();
        fetchProfileData()
        setEditchange(false)
        GenerateToastConfig(res.data.message, 'success');
      } else {
        GenerateToastConfig(res.data.message);
      }
    } catch (err) {
      GenerateToastConfig(err?.response?.data?.message);
    }
  };

  const handleDateChange = (newValue) => {
    setDobs(newValue);
    const currentDate = dayjs();
    const age = currentDate.diff(newValue, 'year');
    setIsAbove18(age >= 18);
    setEditData((prev) => {
      const obj = { ...prev };
      obj.dob = newValue.format(DOBFormat)
      return obj;
    })

  };
  const handleMailChange = (e) => {
    const emailInput = e.target.value;
    setEMails(emailInput);
    setEditData((prev) => {
      const obj = { ...prev };
      obj.email = emailInput
      return obj;
    })

    if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(emailInput)) {
      setEmailError('Invalid email format');
    } else {
      setEmailError('');
    }
  };

  const handleCountryChange = (event) => {
    const country = CountryCode.find(c => c.dial_code === event.target.value);
    setSelectedCountry(country);
    setPhoneCodes(country.dial_code);
    setPhoneNumber('');
  };

  const handlePhoneNumberChange = (event) => {
    const { value } = event.target;
    if (/^\d*$/.test(value)) { // Allow only digits
      setPhoneNumber(value);
      if (selectedCountry && value.length !== PhoneLengthByCountry[selectedCountry.code]) {
        setError('Invalid Phone Number')
      } else {
        setError('');
      }
    }
  };


  const getPhoneNumberInput = () => {
    if (selectedCountry) {
      const maxLength = PhoneLengthByCountry[selectedCountry.code];
      return (
        <InputField
          label={""}
          sx={{ margin: '10px 0px', width: '100%' }}
          inputProps={{ inputMode: 'numeric', pattern: '[0-9]*', maxLength }}
          value={phoneNumber}
          error={!!error}
          helperText={error}
          onChange={handlePhoneNumberChange}
          required
        />
      );
    }
    return (
      <InputField
        label={""}
        sx={{ margin: '10px 0px', width: '100%' }}
        value={phoneNumber}
        onChange={handlePhoneNumberChange}
        required
      />
    )
  };

  const handleImageUpload = async (event) => {
    const file = event.target.files[0]
    const reader = new FileReader()
    setSelectedFile(reader.result)
    const formData = new FormData()
    formData.append('file', file)
    try {
      const res = await axios.put(`module/auth/admin/${data._id}`, formData);
      if (res.status === 200) {
        AdminProfileData()
        fetchProfileData()
        GenerateToastConfig('Profile image updated', 'success')
      }
    } catch (err) {
      GenerateToastConfig(err?.response?.data?.message)
    }


  }
  const handleEditChange = () => {
    setEditchange(true)
  }

  return (
    <>
      <Box>
        <Card sx={{ padding: '30px', marginBottom: '50px' }}>
          <Typography sx={{ fontWeight: 'bold', fontSize: isMobile ? "20px" : '25px', textTransform: 'capitalize' }}>
            {i18?.ACCOUNTSTITLE?.ADMIN_PROFILE || "Admin Profile"}
          </Typography>
        </Card>
      </Box>
      <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center' }}>
        <Card sx={{ padding: '30px', width: '100%' }} variant="outlined" >
          <div style={{ display: 'flex', flexDirection: isMobile ? 'column' : 'row', gap: '30px' }}>
            <div style={{ width: '100%', display: 'flex', justifyContent: 'center', alignItems: 'center' }}>
              <div style={{ width: '250px', height: '250px', objectFit: 'cover', position: 'relative' }}>
                <img
                  src={imageUrl ? `${IMAGE_URL}${imageUrl}` : selectedFile}
                  alt="Selected"
                  style={{ width: '100%', height: '100%', borderRadius: '50%' }}
                />
                <div style={{ position: 'absolute', bottom: '-10px', right: '80px' }}>

                  <label style={{ display: 'flex', gap: '10px', border: '1px solid white', borderRadius: '50px', padding: '5px 10px 5px 10px', alignItems: 'center', backgroundColor: 'white', boxShadow: '5px 5px 10px #888888' }} htmlFor="uploadInput">
                    <CameraAltIcon />
                    <p style={{ marginBottom: '0' }}>{i18?.ACCOUNTSTITLE?.EDIT || "EDIT"}</p>
                  </label>
                  <input
                    id="uploadInput"
                    name="profileImage"
                    type="file"
                    accept="image/*"
                    style={{ display: 'none' }}
                    onChange={handleImageUpload}
                  />
                </div>
              </div>
            </div>
            <div style={{ display: 'flex', flexDirection: "column", gap: '20px', width: '100%', }}>
              <div style={{ display: !isMobile ? 'flex' : "", gap: '10px', alignItems: 'center' }}>
                <>
                  {editchange ?
                    <>
                      <p style={{ fontWeight: 'bold', fontSize: isMobile ? '16px' : '20px', textTransform: 'capitalize', marginBottom: '0px' }}>{i18?.ACCOUNTSTITLE?.NAME || "Name"}:</p>

                      <TextField
                        sx={{ margin: '10px 0px', width: '100%' }}
                        name="FirstName"
                        value={editdata?.firstname}
                        onChange={(e) => {
                          const textInput = e.target.value;
                          // Use a regular expression to check for alphabetic characters only
                          const validTextInput = textInput.replace(/[^a-zA-Z]/g, '');
                          setFname(validTextInput);
                          setEditData((prev) => {
                            const obj = { ...prev };
                            obj.firstname = validTextInput
                            return obj;
                          })
                        }}
                        onKeyDown={(e) => {
                          // Prevent typing numbers and special characters by capturing keydown events
                          if (!/^[a-zA-Z]*$/.test(e.key)) {
                            e.preventDefault();
                          }
                        }}
                      />

                      <TextField
                        sx={{ margin: '10px 0px', width: '100%' }}
                        name="LastName"
                        value={editdata?.lastname}
                        onChange={(e) => {
                          const textInput = e.target.value;
                          // Use a regular expression to check for alphabetic characters only
                          const validTextInput = textInput.replace(/[^a-zA-Z]/g, '');
                          setLname(validTextInput);
                          setEditData((prev) => {
                            const obj = { ...prev };
                            obj.lastname = validTextInput
                            return obj;
                          })
                        }}
                        onKeyDown={(e) => {
                          // Prevent typing numbers and special characters by capturing keydown events
                          if (!/^[a-zA-Z]*$/.test(e.key)) {
                            e.preventDefault();
                          }
                        }}
                      />
                    </>
                    :
                    <div style={{ display: "flex", gap: '10px', alignItems: 'center' }}>
                      <p style={{ fontWeight: 'bold', fontSize: isMobile ? '16px' : '20px', textTransform: 'capitalize', marginBottom: '0px' }}>{i18?.ACCOUNTSTITLE?.NAME || "Name"}:</p>
                      <p style={{ fontWeight: '600', color: 'grey', marginBottom: '0px', marginLeft: '0px' }}>{data?.firstname}
                        {data?.lastname}
                      </p>
                    </div>
                  }

                </>
              </div>
              <div style={{ display: !isMobile ? 'flex' : '', gap: '10px', alignItems: 'center' }}>
                {editchange ? (
                  <>
                    <p style={{ fontWeight: 'bold', fontSize: isMobile ? '16px' : '20px', textTransform: 'capitalize', marginBottom: '0' }}>{i18?.ACCOUNTSTITLE?.EMAIL || "Email"}:</p>
                    <InputField
                      label={""}
                      sx={{ margin: '10px 0px', width: '100%' }}
                      name="Email"
                      error={!!emailError}
                      helperText={emailError}
                      value={editdata?.email}
                      onChange={handleMailChange}
                    />
                  </>
                ) : (
                  <div style={{ display: "flex", gap: '10px', alignItems: 'center' }}>
                    <p style={{ fontWeight: 'bold', fontSize: isMobile ? '16px' : '20px', textTransform: 'capitalize', marginBottom: '0' }}>{i18?.ACCOUNTSTITLE?.EMAIL || "Email"}:</p>
                    <p style={{ fontWeight: '600', color: 'grey', marginBottom: '0' }}>{data?.email}</p>
                  </div>
                )}
              </div>
              <div style={{ display: !isMobile ? 'flex' : '', gap: '10px', alignItems: 'center' }}>
                {editchange ? (
                  <>
                    <p style={{ fontWeight: 'bold', fontSize: isMobile ? '16px' : '20px', textTransform: 'capitalize', marginBottom: '0' }}>{i18?.ACCOUNTSTITLE?.GENDER || "Gender"}:</p>
                    <FormControl fullWidth sx={{ margin: '10px 0px' }}>
                      <Select
                        labelId="demo-simple-select-label"
                        id="demo-simple-select"
                        value={editdata.gender}
                        onChange={(e) => {
                          setGenders(e.target.value);
                          setEditData((prev) => {
                            const obj = { ...prev };
                            obj.gender = e.target.value;
                            return obj;
                          });
                        }}
                        renderValue={(selected) => {
                          if (selected === '') {
                            return <em>{genders}</em>;
                          }
                          return selected;
                        }}
                      >
                        <MenuItem value="male">Male</MenuItem>
                        <MenuItem value="female">Female</MenuItem>
                        <MenuItem value="other">Other</MenuItem>
                      </Select>
                    </FormControl>
                  </>
                ) : (
                  <div style={{ display: "flex", gap: '10px', alignItems: 'center' }}>
                    <p style={{ fontWeight: 'bold', fontSize: isMobile ? '16px' : '20px', textTransform: 'capitalize', marginBottom: '0' }}>{i18?.ACCOUNTSTITLE?.GENDER || "Gender"}:</p>
                    <p style={{ fontWeight: '600', color: 'grey', marginBottom: '0' }}>{data?.gender}</p>
                  </div>
                )}
              </div>
              <div style={{ display: !isMobile ? 'flex' : '', gap: '10px', alignItems: 'center' }}>
                {editchange ? (
                  <>
                    <p style={{ fontWeight: 'bold', fontSize: isMobile ? '16px' : '20px', textTransform: 'capitalize', marginBottom: '0' }}>{i18?.ACCOUNTSTITLE?.DATE_OF_BIRTH || "Date Of Birth"}:</p>
                    <LocalizationProvider dateAdapter={AdapterDayjs} adapterLocale="en-gb">
                      <DemoContainer components={['DatePicker']}>
                        <DatePicker
                          sx={{ width: 1 }}
                          value={editdata?.dob ? dayjs(editdata.dob) : null}
                          disableFuture
                          onChange={handleDateChange}
                        />
                      </DemoContainer>
                    </LocalizationProvider>
                    {!isAbove18 && <p style={{ color: 'red' }}>Age must be above 18</p>}
                  </>
                ) : (
                  <div style={{ display: "flex", gap: '10px', alignItems: 'center' }}>
                    <p style={{ fontWeight: 'bold', fontSize: isMobile ? '16px' : '20px', textTransform: 'capitalize', marginBottom: '0' }}>{i18?.ACCOUNTSTITLE?.DATE_OF_BIRTH || "Date Of Birth"}:</p>
                    <p style={{ fontWeight: '600', color: 'grey', marginBottom: '0' }}>{DateFormat(data?.dob)}</p>
                  </div>
                )}
              </div>
              <div style={{ display: !isMobile ? 'flex' : '', gap: '10px', alignItems: 'center' }}>
                {editchange ? (
                  <>
                    <p style={{ fontWeight: 'bold', fontSize: isMobile ? '16px' : '20px', textTransform: 'capitalize', marginBottom: '0', whiteSpace: 'nowrap' }}>{i18?.ACCOUNTSTITLE?.PHONE_NUMBER || "Phone Number"}:</p>
                    <FormControl fullWidth sx={{ margin: '10px 0px' }}>
                      <Select
                        labelId="demo-simple-select-label"
                        id="demo-simple-select"
                        value={phoneCodes}
                        onChange={handleCountryChange}
                        MenuProps={MenuProps}
                      >
                        {CountryCode.map((data) => (
                          <MenuItem key={data.code} value={data.dial_code}>{data.name} &nbsp;&nbsp; {data.dial_code}</MenuItem>
                        ))}
                      </Select>
                    </FormControl>
                    {getPhoneNumberInput()}
                  </>
                ) : (
                  <div style={{ display: "flex", gap: '10px', alignItems: 'center' }}>
                    <p style={{ fontWeight: 'bold', fontSize: isMobile ? '16px' : '20px', textTransform: 'capitalize', marginBottom: '0', whiteSpace: 'nowrap' }}>{i18?.ACCOUNTSTITLE?.PHONE_NUMBER || "Phone Number"}:</p>
                    <p style={{ fontWeight: '600', color: 'grey', marginBottom: '0', whiteSpace: 'nowrap' }}> {phoneCodes} - {data?.phone}</p>
                  </div>
                )}
              </div>
              <div style={{ fontWeight: '600', color: 'grey' }}>
                {data?.isActive ? (
                  <span>
                    <span style={{ color: 'green', fontSize: '20px' }}>&#9679;</span> Active
                  </span>
                ) : (
                  <span>
                    <span style={{ color: 'red', fontSize: '20px' }}>&#9679;</span> Inactive
                  </span>
                )}
              </div>
              <div style={{ fontWeight: '600', color: 'grey' }}>
                {data?.verified ? (
                  <span>
                    <span style={{ color: 'green', fontSize: '20px' }}>&#9679;</span> Verified
                  </span>
                ) : (
                  <span>
                    <span style={{ color: 'red', fontSize: '20px' }}>&#9679;</span> Unverified
                  </span>
                )}
              </div>
            </div>
          </div>
          <div style={{ display: 'flex', justifyContent: 'end', flexDirection: isMobile ? 'column' : 'row', gap: isMobile ? '10px' : '20px', paddingTop: '20px' }}>
            {editchange ? (
              <div style={{ display: 'flex', flexDirection: isMobile ? 'column' : 'row', gap: isMobile ? '10px' : '20px', width: isMobile ? '100' : 'auto' }}>
                <Button variant="contained" fullWidth={isMobile} onClick={() => setEditchange(false)}> {i18?.ACCOUNTSTITLE?.CLOSE || "Close"} </Button>
                <Button variant="contained" fullWidth={isMobile} onClick={EditAdmin}> {i18?.ACCOUNTSTITLE?.UPDATE || "Update"} </Button>
              </div>
            ) : <Button variant="contained" fullWidth={isMobile} onClick={handleEditChange}> {i18?.ACCOUNTSTITLE?.EDIT || "Edit"} </Button>}
          </div>
        </Card>
      </div>
    </>
  );
}

export default AdminProfile;
